code.functions:
// 1. greet(name) with a default of "friend"
function greet(name="friend") {
  return `Hello, ${name}!`
}

// 2. square as an arrow function
const square = (n) => n*n;

// 3. applyTwice(fn, x)
function applyTwice(fn, x) {
  return fn(fn(x));
}

// Try them out:
console.log(greet("Ada"));
console.log(greet());
console.log(applyTwice(square, 3))

code.conditionals:
function grade(score) {
  if (score >= 90) {
    return "A"
  } else if (score >= 80) {
    return "B"
  } else if (score >= 70) {
    return "C"
  } else {
    return "F"
    }
}

const parity = (n) => {
  const result = n % 2 === 0 ? "even" : "odd";
  return result
};

console.log(grade(95), grade(85), grade(72), grade(40));
console.log(parity(4), parity(7));

